package com.javafundamentals;

public class Datatypes {
	
	
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		byte age=22;
		short NoOfStudents=150;
		int AnnualSalary=35000;
		long Population=789012L;
		float Marks=8.32f;
		double BankBalance=25000.90D;
		char Grade='A';
		boolean JavaLearner=true;
		
		    System.out.println("Age: " + age);
	        System.out.println("NoOfStudents: " + NoOfStudents);
	        System.out.println("AnnualSalary: " + AnnualSalary);
	        System.out.println("Population: " + Population);
	        System.out.println("Marks: " + Marks);
	        System.out.println("BankBalance:" + BankBalance);
	        System.out.println("Grade: " + Grade);
	        System.out.println("JavaLearner: " + JavaLearner);
		

	}

}
